/* prog21_date_validator.c
 *
 * Re‑implementation of the original binary’s observable behaviour.
 * The program validates a date given as the first command‑line argument.
 *
 * Usage: prog21_date_validator <date>
 *
 * The date must be exactly 10 characters long and follow the format
 *   YYYY-MM-DD
 * where YYYY, MM and DD are decimal numbers.
 * The month must be 1‑12 and the day must be valid for the month,
 * taking leap years into account.
 *
 * Output:
 *   VALID   – if the supplied string is a correct date
 *   INVALID – otherwise (including missing argument)
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

/* Return true if the given year is a leap year in the Gregorian calendar. */
static bool is_leap_year(int year)
{
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

/* Return the number of days in the given month of the given year.
 * month is 1‑based (1 = January). */
static int days_in_month(int year, int month)
{
    static const int days[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    if (month == 2 && is_leap_year(year))
        return 29;
    return days[month - 1];
}

/* Validate a string of the form YYYY-MM-DD.
 * Returns true for a valid date, false otherwise. */
static bool validate_date(const char *s)
{
    /* Length must be exactly 10 */
    if (strlen(s) != 10)
        return false;

    /* Positions 4 and 7 must be '-' */
    if (s[4] != '-' || s[7] != '-')
        return false;

    /* All other characters must be decimal digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (s[i] < '0' || s[i] > '9')
            return false;
    }

    /* Parse the numeric fields */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Month must be 1‑12 */
    if (month < 1 || month > 12)
        return false;

    /* Day must be at least 1 and not exceed the month’s length */
    if (day < 1 || day > days_in_month(year, month))
        return false;

    return true;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
